/**
 * Item com estoque controlado baixa a quantidade na hora (409 se não houver). Funeral concluído ou cancelado não muda.
 * @summary Inclui um item do catálogo no funeral
 */
export const adicionarItemFuneral = async (
  id: string,
  itemFuneralRequest: ItemFuneralRequest,
  options?: Parameters<typeof requisicao>[1],
): Promise<ComposicaoItensResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return requisicao<ComposicaoItensResponse>(getAdicionarItemFuneralUrl(id), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(itemFuneralRequest),
  });
};

